 1	
 2	predicate sorted_seg(a:array<int>, i:int, j:int) //i and j included
 3	requires 0 <= i <= j+1 <= (a.Length) + 1
 4	reads a
 5	{
 6	    forall l, k :: i <= l <= k <= j ==> a[l] <= a[k]
 7	}
 8	
 9	method InsertionSort(a: array<int>)
10	  modifies a;
11	  ensures sorted_seg(a,0,a.Length-1) 
12	  ensures multiset(a[..]) == old(multiset(a[..])) //Add and prove this
13	{
14	
15	  var i := 0;
16	  assert multiset(a[..]) == old(multiset(a[..]));
17	  while (i < a.Length)
18	     decreases a.Length-i
19	     invariant 0<=i<=a.Length
20	     invariant sorted_seg(a,0,i-1)
21	     invariant multiset(a[..]) == old(multiset(a[..]))//add
22	    invariant forall k::i<k<a.Length ==> a[k] == old(a[k])
23	  {
24	
25	     var temp := a[i];
26	     var j := i;         
27	     while (j > 0 && temp < a[j - 1])
28	         decreases j
29	         invariant 0<=j<=i
30	         invariant sorted_seg(a,0,j-1) && sorted_seg(a,j+1,i)
31	         invariant forall k,l :: 0<=k<=j-1 && j+1<=l<=i ==> a[k]<=a[l]
32	         invariant forall k :: j<k<=i ==> temp <a[k]
33	         invariant forall k::i<k<a.Length ==> a[k] == old(a[k])
34	         invariant multiset(a[..]) - multiset{a[j]} + multiset{temp} == old(multiset(a[..]))//add
35	     {   
36	        
37	         a[j] := a[j - 1]; 
38	         j := j - 1;
39	     }
40	  
41	  
42	  a[j] := temp;
43	  i := i + 1;
44	
45	  }
46	}
